package jp.nw.model;import java.sql.*;import java.util.*;import jp.nw.parts.DBBase;
public class AttachmentLogic{public List<Map<String,Object>> find(String type,String id){DBBase db=new DBBase();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT attachment_id,original_name,content_type,file_size,created_at FROM attachment WHERE owner_type=? AND owner_id=? ORDER BY created_at")){p.setString(1,type);p.setString(2,id);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("attachment_id",r.getLong(1));m.put("original_name",r.getString(2));m.put("content_type",r.getString(3));m.put("file_size",r.getLong(4));m.put("created_at",r.getTimestamp(5));out.add(m);}return out;}}catch(SQLException e){throw new RuntimeException(e);}}}
